[CmdletBinding()]
param([string]$ConfigPath=$null,[string]$CodexHome)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
if([string]::IsNullOrWhiteSpace($ConfigPath)){$ConfigPath=Join-Path $root 'config\agents.json'}
$temp=Join-Path ([IO.Path]::GetTempPath()) ('ecosystem-stability-ops-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $temp -Force|Out-Null
try {
 $metric=Join-Path $temp 'metric';New-Item -ItemType Directory -Path $metric|Out-Null;$attempt=[guid]::NewGuid().ToString('N');$writer=Join-Path $root 'scripts\Write-RoleAttemptMetric.ps1'
 $writerArgs="-NoProfile -File `"$writer`" -TaskRoot `"$metric`" -TaskId task-race -AttemptId $attempt -RunId run-race -LeaseId lease-race -AgentId reviewer -ConfiguredMode classic -EffectiveMode classic -Status succeeded -DurationMs 1"
 $psExe=(Get-Command powershell.exe -ErrorAction Stop).Source;$jobs=@(1..6|ForEach-Object{Start-Process -FilePath $psExe -ArgumentList $writerArgs -PassThru -WindowStyle Hidden});$jobs|ForEach-Object{try{if(-not $_.WaitForExit(15000)){throw 'Metric writer did not finish.'};if($_.ExitCode -ne 0){throw "Metric writer failed: $($_.ExitCode)"}}finally{$_.Dispose()}}
 $records=@(Get-Content -LiteralPath (Join-Path $metric 'role-metrics.jsonl')|Where-Object{$_}|ForEach-Object{$_|ConvertFrom-Json});if($records.Count -ne 1){throw "Duplicate metric race wrote $($records.Count) records."}
 $cfg=Get-Content -LiteralPath $ConfigPath -Raw|ConvertFrom-Json;$cfg.runtime.stateRoot=Join-Path $temp 'state';$cfgPath=Join-Path $temp 'agents.json';$cfg|ConvertTo-Json -Depth 80|Set-Content -LiteralPath $cfgPath -Encoding UTF8
 $health=Join-Path $cfg.runtime.stateRoot 'health';New-Item -ItemType Directory -Path $health -Force|Out-Null;@{schemaVersion='1.0.0';kind='scheduled-review';mode='daily';status='failed';checkedAtUtc=[DateTime]::UtcNow.ToString('o');error=@{classification='runner';summary='synthetic failure'}}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $health 'scheduled-review-daily.json') -Encoding UTF8
 $report=& (Join-Path $root 'scripts\Get-EcosystemStabilityReport.ps1') -ConfigPath $cfgPath -CodexHome $CodexHome;if($null -ne $report.Report.slo.taskCompletionRate){throw 'Report must not treat task completion as an SLO.'}
 $task=Join-Path $cfg.runtime.stateRoot 'tasks\report-task';New-Item -ItemType Directory -Path $task -Force|Out-Null;@{taskId='report-task';status='running'}|ConvertTo-Json|Set-Content (Join-Path $task 'task.json') -Encoding UTF8;@{summary='OAuth session expired';executionRunId='';executionAttemptId=''}|ConvertTo-Json|Set-Content (Join-Path $task 'agent-failure-x.json') -Encoding UTF8;$classified=& (Join-Path $root 'scripts\Get-EcosystemStabilityReport.ps1') -ConfigPath $cfgPath -CodexHome $CodexHome;if($classified.Report.activeFailures.'provider-authentication' -ne 1 -or $classified.Report.missingIdentity.failureRecordsWithoutRunId -ne 1){throw 'Report did not classify expected external auth or missing IDs.'}
 $observedMetrics=Join-Path $task 'role-metrics.jsonl'
 $m1=@{eventType='role-attempt-completed';taskId='report-task';runId='r1';attemptId='same-attempt';status='succeeded';executionBundleFingerprint='bundle-a'}
 $m2=@{eventType='role-attempt-completed';taskId='report-task';runId='r2';attemptId='same-attempt';status='failed';executionBundleFingerprint='bundle-a'}
 @((($m1|ConvertTo-Json -Compress)),(($m1|ConvertTo-Json -Compress)),(($m2|ConvertTo-Json -Compress)),'{"eventType":"role-attempt-completed","taskId":"report-task"}','malformed-json')|Set-Content -LiteralPath $observedMetrics -Encoding UTF8
 @('{"eventType":"lock-acquisition","waitMs":1,"holdMs":2}','{"eventType":"lock-acquisition","waitMs":5,"holdMs":6}','{"eventType":"lock-acquisition","waitMs":9,"holdMs":10}','{}')|Set-Content -LiteralPath (Join-Path $health 'lock-metrics.jsonl') -Encoding UTF8
 $resumeGood=@{type='targeted-resume-completed';attemptId='resume-a';failureSignature=('a'*64);ecosystemRepairStatus='repaired';status='completed'}
 $resumeBad=@{type='targeted-resume-failed';attemptId='resume-b';failureSignature=('a'*64);ecosystemRepairStatus='repaired';status='failed'}
 @((($resumeGood|ConvertTo-Json -Compress)),(($resumeGood|ConvertTo-Json -Compress)),(($resumeBad|ConvertTo-Json -Compress)),'{"failureSignature":"uncorrelated"}')|Set-Content -LiteralPath (Join-Path $task 'health-targeted-resume-attempts.jsonl') -Encoding UTF8
 $known=(& (Join-Path $root 'scripts\Get-EcosystemStabilityReport.ps1') -ConfigPath $cfgPath -CodexHome $CodexHome).Report
 if($known.attemptCohort.uniqueTaskRunAttemptCount -ne 2 -or $known.attemptCohort.excludedDuplicateLines -ne 1 -or $known.attemptCohort.excludedSparseLines -ne 1 -or $known.attemptCohort.excludedMalformedLines -ne 1){throw 'Report lost exact attempt identity, sparse/malformed or duplicate exclusions.'}
 if($known.lockMetrics.sampleCount -ne 3 -or $known.lockMetrics.excludedCount -ne 1 -or $known.lockMetrics.p50WaitMs -ne 5 -or $known.lockMetrics.p95WaitMs -ne 9 -or $known.lockMetrics.p50HoldMs -ne 6){throw 'Report percentile evidence was incorrect.'}
 if($known.repairedAndResumed.denominator -ne 2 -or $known.repairedAndResumed.count -ne 1 -or $known.repairedAndResumed.rate -ne .5){throw 'Report invented or duplicated repair/resume correlation.'}
 $fixtureMonitor=Join-Path $temp 'monitor';New-Item -ItemType Directory -Path (Join-Path $fixtureMonitor 'scripts\providers') -Force|Out-Null;Set-Content (Join-Path $fixtureMonitor 'scripts\agent_config.ps1') 'function Read-AgentConfig { param($Path) Get-Content $Path -Raw|ConvertFrom-Json }; function Get-AgentCredentialProfile { param($Config,$Repository) @{} }';Set-Content (Join-Path $fixtureMonitor 'scripts\providers\provider_dispatch.ps1') 'function Get-ProviderPullRequests { param($Repository,$Profile) @() }'
 $runner=Join-Path $fixtureMonitor 'scripts\run_pr_review_monitor.ps1';Set-Content $runner "param([Parameter(ValueFromRemainingArguments=`$true)]`$Rest); 'synthetic-success'"
 $cfg.review.monitorSkillRoot=$fixtureMonitor;$cfg.review.monitorDataRoot=Join-Path $temp 'review-data';$cfg.review.generatedPromptRoot=Join-Path $temp 'review-prompts';$cfg|ConvertTo-Json -Depth 80|Set-Content $cfgPath -Encoding UTF8
 $wrapper=Join-Path $root 'scripts\Invoke-EnhancedReview.ps1';$success=@(& $psExe -NoProfile -File $wrapper -Mode Daily -ConfigPath $cfgPath 2>&1);$successExit=$LASTEXITCODE;if($successExit -ne 0 -or $success.Count -ne 1 -or [string]$success[0] -ne 'synthetic-success'){throw ('Healthy wrapper did not preserve runner output. exit='+$successExit+' count='+$success.Count+' output='+($success|ForEach-Object{[string]$_}|Out-String))};$status=Get-Content (Join-Path $health 'scheduled-review-daily.json') -Raw|ConvertFrom-Json;if($status.status -ne 'succeeded' -or -not $status.lastSucceededAtUtc){throw 'Healthy wrapper did not record last success.'}
 Set-Content $runner "param([Parameter(ValueFromRemainingArguments=`$true)]`$Rest); [Console]::Error.WriteLine('Authorization: Bearer topsecret apiKey=alsosecret'); exit 7";$stderr=Join-Path $temp 'wrapper-failure.stderr';$failure=Start-Process -FilePath $psExe -ArgumentList ('-NoProfile -File "'+$wrapper+'" -Mode Daily -ThrowOnFailure -ConfigPath "'+$cfgPath+'"') -RedirectStandardError $stderr -PassThru -WindowStyle Hidden;try{$failure.WaitForExit();if($failure.ExitCode -eq 0){throw 'ThrowOnFailure did not fail scheduled process.'}}finally{$failure.Dispose()};$status=Get-Content (Join-Path $health 'scheduled-review-daily.json') -Raw|ConvertFrom-Json;if($status.status -ne 'failed' -or $status.error.summary -match 'topsecret|alsosecret' -or -not $status.lastSucceededAtUtc){throw 'Failed wrapper did not redact error or preserve last success.'}
 # Parse on both scheduled-task Windows PowerShell and current pwsh without invoking review providers.
 & $psExe -NoProfile -Command "[scriptblock]::Create([IO.File]::ReadAllText('$root\scripts\Invoke-EnhancedReview.ps1'))|Out-Null";if($LASTEXITCODE){throw 'Windows PowerShell cannot parse review wrapper.'};& pwsh -NoProfile -Command "[scriptblock]::Create([IO.File]::ReadAllText('$root\scripts\Invoke-EnhancedReview.ps1'))|Out-Null";if($LASTEXITCODE){throw 'pwsh cannot parse review wrapper.'}
 [pscustomobject]@{Passed=$true;Checks=@('multiprocess role metric idempotency','evidenced null SLO','wrapper synthetic healthy and failing paths','Windows PowerShell and pwsh wrapper parse')}
} finally {if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
